// Кейс: .qa/tests/monitoring/MON-036.md шаг 1 · план: .qa/e2e-app/specs/app.md (1.56)
// iPhone — камера, Pixel (adb) стоит на «בית» и не трогается. Мониторинг → «כבה את המצלמה» → на Pixel новая строка первой в «ניטורים אחרונים»
// за ≤ BANCI_RECENT_SEC с (по умолчанию 15; ориентир программиста ~10 с), без дублей. ЗАПУСКАЕТ МОНИТОРИНГ — BANCI_MONITORING=1 + BANCI_ANDROID_SERIAL.
import { assert } from '../../lib/appium.mjs';
import { startMonitoring, endMonitoring, waitTimer } from '../../lib/monitoring.mjs';
import { requireSecondPhone, pixelHome, recentRows, waitNewRow } from '../../lib/second-phone.mjs';

export const name = '«ניטורים אחרונים» на втором телефоне: после «כבה את המצלמה» на iPhone новая строка первой за ≤ 15 с, без ухода с «בית» #7f31a2 @iphone @app @data';

export default async function (app) {
  const pixel = await requireSecondPhone();
  await pixelHome(pixel);
  const before = await recentRows(pixel);

  await startMonitoring(app);
  await waitTimer(app, 20);
  await endMonitoring(app);

  const { rows, row, sec } = await waitNewRow(pixel, before);
  console.log(`     новая строка на Pixel через ${sec.toFixed(1)} с: ${row}`);
  assert(rows[0] === row, `новая строка «${row}» — первая в списке (сейчас сверху: ${rows[0]})`);
  assert(rows.filter((r) => r === row).length === 1, 'новая строка не задвоена');
}
